package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// PoolWorker представляет пул воркеров, который обрабатывает задачи из канала
// с ограничением параллелизма. Пул использует фиксированное количество горутины-воркеров,
// которые одновременно выполняют задачи. Задачи поступают через канал и распределяются
// между свободными воркерами.
type PoolWorker struct {
	// numWorkers — количество воркеров в пуле (ограничение параллелизма).
	numWorkers int

	// taskChan — канал для приёма задач. Каждая задача — это функция без аргументов и возвращаемых значений.
	taskChan chan func()

	// ctx — контекст для управления жизненным циклом пула.
	// При отмене контекста все воркеры завершают работу.
	ctx context.Context

	// cancel — функция отмены контекста. Вызывается методом Stop().
	cancel context.CancelFunc

	// wg — WaitGroup для ожидания завершения всех воркеров.
	wg sync.WaitGroup
}

// NewPoolWorker создаёт новый экземпляр пула воркеров.
//
// Параметры:
//   - numWorkers: количество воркеров (параллельных горутины), которые будут обрабатывать задачи.
//     Значение должно быть положительным; если передано <= 0, будет использовано значение 1.
//
// Возвращает указатель на созданный пул. Пул сразу начинает работать:
// воркеры запускаются и ожидают задачи из канала.
func NewPoolWorker(numWorkers int) *PoolWorker {
	// Защита от некорректного значения numWorkers.
	if numWorkers <= 0 {
		numWorkers = 1
	}

	// Создаём контекст с возможностью отмены.
	// Контекст используется для корректного завершения работы воркеров.
	ctx, cancel := context.WithCancel(context.Background())

	p := &PoolWorker{
		numWorkers: numWorkers,
		taskChan:   make(chan func(), numWorkers*2), // Буферизация: позволяет буферизовать несколько задач, чтобы отправитель не блокировался мгновенно.
		ctx:        ctx,
		cancel:     cancel,
	}

	// Запускаем воркеры.
	p.startWorkers()

	return p
}

// startWorkers запускает указанное количество горутины-воркеров.
// Каждый воркер бесконечно читает задачи из канала taskChan и выполняет их,
// пока не будет отменён контекст или закрыт канал.
func (p *PoolWorker) startWorkers() {
	for i := 0; i < p.numWorkers; i++ {
		// Регистрируем воркер в WaitGroup, чтобы Stop() мог дождаться его завершения.
		p.wg.Add(1)

		go p.worker(i)
	}
}

