 * @param price   Исходная цена (BigDecimal)
 * @param percent Процент скидки (целое число от 0 до 100 включительно)
 * @return Цена после применения скидки, округленная до 2 знаков после запятой
 * @throws IllegalArgumentException если процент скидки вне диапазона [0, 100]
 */
public BigDecimal applyDiscount(BigDecimal price, int percent) {
    // Проверяем, что процент скидки находится в допустимом диапазоне: от 0 до 100.
    // Если нет — бросаем исключение с сообщением об ошибке.
    if (percent < 0 || percent > 100) throw new IllegalArgumentException("percent");

    // Вычисляем коэффициент умножения: сколько процентов цены остаётся после скидки.
    // Например, при скидке 20% коэффициент будет (100 - 20) / 100 = 0.8
    BigDecimal k = BigDecimal.valueOf(100 - percent).divide(BigDecimal.valueOf(100));

    // Умножаем исходную цену на коэффициент и округляем результат до 2 знаков после запятой
    // по правилу HALF_EVEN (округление до чётного числа), чтобы избежать систематических ошибок округления.
    return price.multiply(k).setScale(2, RoundingMode.HALF_EVEN);
}
