// Метод Get извлекает значение по ключу из кэша.
// Возвращает строку со значением и булево значение, указывающее на успех операции.
func (c *Cache) Get(key string) (string, bool) {
    // Приобретаем блокировку для чтения (RLock), чтобы обеспечить безопасный доступ к данным
    // при одновременном чтении несколькими горутинами.
    c.mu.RLock()

    // Ищем элемент в мапе items по указанному ключу.
    // e — это сам элемент кэша, ok — флаг наличия ключа в мапе.
    e, ok := c.items[key]

    // Освобождаем блокировку для чтения, так как данные уже получены.
    c.mu.RUnlock()

    // Проверяем, был ли найден ключ (ok == true) и не истекло ли время жизни элемента.
    // Если ключ не найден или срок действия истек, возвращаем пустую строку и false.
    if !ok || time.Now().After(e.expires) {
        return "", false
    }

    // Если элемент найден и еще действителен, возвращаем его значение и true.
    return e.value, true
}
