/**
 * Создаёт дебаунс-обёртку для переданной функции.
 * Дебаунс откладывает выполнение функции до тех пор, пока не пройдёт заданное время (ms)
 * после последнего вызова обёрнутой функции. Это полезно, например, для обработки
 * событий ввода в поле поиска или изменения размера окна, чтобы избежать лишних
 * вычислений при частых срабатываниях.
 *
 * @param fn - Функция, которую нужно обернуть в дебаунс.
 * @param ms - Задержка в миллисекундах, по истечении которой функция будет выполнена.
 * @returns Возвращает новую функцию с той же сигнатурой параметров, что и `fn`,
 *          но с отложенным выполнением.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Она используется для отмены предыдущего запланированного выполнения,
  // если функция была вызвана снова до истечения задержки.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и оригинальная `fn`.
  return (...args: Parameters<T>) => {
    // Если существует активный таймер (т.е., функция уже была вызвана ранее
    // и ожидает исполнения), отменяем его.
    // Это гарантирует, что функция выполнится только один раз — через `ms` мс
    // после самого последнего вызова.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на задержку `ms`.
    // По истечении этого времени будет вызвана оригинальная функция `fn`
    // с теми аргументами (`args`), которые были переданы при последнем вызове.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

