/**
 * Универсальная функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока (включая первую).
 * @param block Лямбда-функция, содержащая код, который нужно выполнить.
 * @return Результат выполнения блока, если он завершился успешно.
 * @throws IOException Если все попытки завершились исключением IOException.
 * @throws IllegalStateException Если передано количество попыток <= 0.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последнего возникшего исключения, чтобы бросить его в конце,
    // если все попытки исчерпаны.
    var last: Throwable? = null

    // Цикл, выполняющий блок `times` раз.
    repeat(times) {
        try {
            // Пытаемся выполнить блок кода.
            // Если выполнение успешное — сразу возвращаем результат и выходим из функции.
            return block()
        } catch (e: IOException) {
            // Если произошло исключение IOException, сохраняем его в переменную `last`.
            // Это позволит нам позже определить, какое именно исключение было последним,
            // и передать его наружу.
            last = e
        }
    }

    // Если цикл завершился без возврата результата (то есть все попытки упали с IOException),
    // бросаем последнее сохраненное исключение.
    // Если `last` равно null (что возможно только при times <= 0), бросаем IllegalStateException,
    // так как логика ретраев не имеет смысла при нулевом или отрицательном количестве попыток.
    throw last ?: IllegalStateException("times must be > 0")
}
```

