///
/// # Аргументы
/// * `v` - ссылка на изменяемый вектор `f64`. Вектор будет отсортирован на месте.
///
/// # Возвращаемое значение
/// * `Some(f64)` - медиана, если вектор не пуст.
/// * `None` - если вектор пуст.
pub fn median(v: &mut Vec<f64>) -> Option<f64> {
    // Если вектор пуст, медиана не определена, возвращаем None
    if v.is_empty() { return None; }

    // Сортируем вектор по возрастанию значений.
    // Используем partial_cmp, так как f64 может содержать NaN или бесконечности,
    // для которых полная сравнение (cmp) не применимо.
