    v.sort_by(|a, b| a.partial_cmp(b).unwrap());

    // Индекс среднего элемента (для нечётной длины) или правого из двух средних (для чётной)
    let m = v.len() / 2;

    // Возвращаем Some(median):
    // - Если длина чётная: берём среднее арифметическое двух центральных элементов (m-1 и m)
    // - Если длина нечётная: берём элемент с индексом m (центральный)
    Some(if v.len() % 2 == 0 { 
        (v[m - 1] + v[m]) / 2.0 
    } else { 
        v[m] 
    })
}
